287	/// Calling thread's last FFI exception message, ready to append to an error;
288	/// empty unless `result` is the -1 sentinel set by the C++ guard. Public for
289	/// crates that call guarded FFI entries directly instead of through a wrapper.
290	pub fn ffi_exception_message(result: i32) -> String {
291	    if result != -1 {
292	        return String::new();
293	    }
294	    let ptr = unsafe { crate::ffi::pegainfer_kernels_last_error() };
295	    if ptr.is_null() {
296	        return String::new();
297	    }
298	    let text = unsafe { std::ffi::CStr::from_ptr(ptr) }.to_string_lossy();
299	    if text.is_empty() {
300	        String::new()
301	    } else {
302	        format!(": {text}")
303	    }
304	}
305	
306	/// `PEGAINFER_CUBLAS_STATUS_BASE` in `csrc/shared/ffi_guard.cuh`: an entry
307	/// point that calls cuBLAS returns it plus the `cublasStatus_t` on a cuBLAS
308	/// failure, and the `cudaError_t` otherwise.
309	pub const CUBLAS_STATUS_BASE: i32 = 100_000;
310	
311	/// Name a nonzero status from such an entry point, for an error message.
312	pub fn ffi_status_detail(status: i32) -> String {
313	    if status >= CUBLAS_STATUS_BASE {
314	        format!("cublas_status={}", status - CUBLAS_STATUS_BASE)
315	    } else {
316	        format!("cuda_status={status}")
317	    }
318	}
