410	    x.checked_extent("rms_norm_add_scale_batch_into x")?;
411	    residual.checked_extent("rms_norm_add_scale_batch_into residual")?;
412	    out.checked_extent("rms_norm_add_scale_batch_into out")?;
413	    let hidden_dim = super::checked_i32(x.hidden_dim, "rms_norm_add_scale_batch_into hidden_dim")?;
414	    let seq_len = super::checked_i32(x.seq_len, "rms_norm_add_scale_batch_into seq_len")?;
415	    let (x_ptr, _gx) = x.data.device_ptr(&ctx.stream);
416	    let (w_ptr, _gw) = weight.data.device_ptr(&ctx.stream);
417	    let (r_ptr, _gr) = residual.data.device_ptr(&ctx.stream);
418	    let (o_ptr, _go) = out.data.device_ptr_mut(&ctx.stream);
419	    let result = unsafe {
420	        ffi::rms_norm_add_scale_batched_cuda(
421	            x_ptr as *const ffi::Half,
422	            w_ptr as *const ffi::Half,
423	            r_ptr as *const ffi::Half,
424	            o_ptr as *mut ffi::Half,
425	            hidden_dim,
426	            seq_len,
427	            eps,
428	            scale,
429	            crate::tensor::active_cu_stream(ctx),
