631	/// Which activation multiplies a gated RMSNorm's output.
632	///
633	/// Qwen3.5's Gated DeltaNet uses [`GatedNormActivation::Silu`].
634	/// Qwen3.8-Flash-Next declares `output_gate_type: "sigmoid"`, and its reference
635	/// implementation passes that field straight to the gated norm, so the same
636	/// kernel has to serve both. Note the *attention* output gate is a hardcoded
637	/// sigmoid on both lines; this enum is only about the gated norm.
638	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
639	pub enum GatedNormActivation {
640	    Silu,
641	    Sigmoid,
642	}
643	
644	/// Batched per-head RMSNorm with F32 weight + a gated activation multiplies.
645	/// HiddenStates are flattened as (seq_len * num_heads) contiguous head slices.
646	/// The gate may be one band of a fused projection, in which case its slot stride
647	/// is the tensor it is a band of rather than the band's own width.
648	/// `activation` chooses the gate: Qwen3.5's Gated DeltaNet passes
649	/// [`GatedNormActivation::Silu`], Qwen3.8-Flash-Next's passes `Sigmoid`.
650	#[allow(clippy::too_many_arguments)]
651	pub fn rms_norm_gated_batch_into<'a>(
652	    ctx: &DeviceContext,
653	    x: &HiddenStates,
654	    weight: &CudaSlice<f32>,
655	    gate: impl Into<Columns<'a>>,
656	    out: &mut HiddenStates,
657	    num_heads: usize,
658	    head_dim: usize,
659	    eps: f32,
660	    activation: GatedNormActivation,
661	) {
662	    let gate = gate.into();
663	    gate.assert_in_row("rms_norm_gated gate");
664	    let total_heads = x.seq_len * num_heads;
665	    assert_eq!(x.hidden_dim, num_heads * head_dim);
666	    assert_eq!(gate.width, x.hidden_dim);
667	    assert_eq!(gate.states.seq_len, x.seq_len);
668	    assert_eq!(out.hidden_dim, x.hidden_dim);
669	    assert_eq!(out.seq_len, x.seq_len);
670	    let (x_ptr, _gx) = x.data.device_ptr(&ctx.stream);
671	    let (w_ptr, _gw) = weight.device_ptr(&ctx.stream);
672	    let (g_ptr, _gg) = gate.states.data.device_ptr(&ctx.stream);
673	    let g_ptr = g_ptr + (gate.col * std::mem::size_of::<bf16>()) as u64;
674	    let (o_ptr, _go) = out.data.device_ptr_mut(&ctx.stream);
675	    let stream = crate::tensor::active_cu_stream(ctx);
676	    unsafe {
677	        match activation {
678	            GatedNormActivation::Silu => ffi::rms_norm_gated_cuda(
679	                x_ptr as *const ffi::Half,
680	                w_ptr as *const f32,
681	                g_ptr as *const ffi::Half,
682	                o_ptr as *mut ffi::Half,
683	                total_heads as i32,
684	                num_heads as i32,
685	                head_dim as i32,
686	                x.hidden_dim as i32,
687	                gate.states.hidden_dim as i32,
688	                eps,
689	                stream,
690	            ),
691	            GatedNormActivation::Sigmoid => ffi::rms_norm_gated_sigmoid_cuda(
692	                x_ptr as *const ffi::Half,
693	                w_ptr as *const f32,
694	                g_ptr as *const ffi::Half,
695	                o_ptr as *mut ffi::Half,
696	                total_heads as i32,
697	                num_heads as i32,
698	                head_dim as i32,
699	                x.hidden_dim as i32,
700	                gate.states.hidden_dim as i32,
701	                eps,
702	                stream,
703	            ),
704	        }
705	    }
706	}
