850	    /// CPU reference for the per-head gated RMSNorm, in f64 then rounded to bf16.
851	    /// The kernel reduces in f32 with a warp tree, so this is an oracle with a
852	    /// bf16-sized tolerance, not a bit-exact model.
853	    fn gated_norm_reference(
854	        x: &[bf16],
855	        weight: &[f32],
856	        gate: &[bf16],
857	        head_dim: usize,
858	        eps: f32,
859	        sigmoid: bool,
860	    ) -> Vec<bf16> {
861	        let mut out = vec![bf16::from_f32(0.0); x.len()];
862	        for head in 0..(x.len() / head_dim) {
863	            let base = head * head_dim;
864	            let mut sumsq = 0.0f64;
865	            for t in 0..head_dim {
866	                let v = f64::from(x[base + t].to_f32());
867	                sumsq += v * v;
868	            }
869	            let inv_rms = 1.0 / (sumsq / head_dim as f64 + f64::from(eps)).sqrt();
870	            for t in 0..head_dim {
871	                let normed = f64::from(x[base + t].to_f32()) * inv_rms * f64::from(weight[t]);
872	                let g = f64::from(gate[base + t].to_f32());
873	                let sigma = 1.0 / (1.0 + (-g).exp());
874	                let activated = if sigmoid { sigma } else { g * sigma };
875	                out[base + t] = bf16::from_f32((normed * activated) as f32);
876	            }
877	        }
878	        out
879	    }
880	
881	    fn assert_close(got: &[bf16], want: &[bf16], what: &str) {
882	        assert_eq!(got.len(), want.len(), "{what} length");
883	        assert!(!got.is_empty(), "{what}: nothing to compare");
884	        let tolerance = |magnitude: f64| 0.02 + 0.03 * magnitude;
885	        let mut worst = (0usize, 0.0f64, 0.0f64);
886	        let mut worst_excess = f64::NEG_INFINITY;
887	        for (index, (got_value, want_value)) in got.iter().zip(want).enumerate() {
888	            let (got_value, want_value) = (
889	                f64::from(got_value.to_f32()),
890	                f64::from(want_value.to_f32()),
891	            );
892	            let (abs_diff, magnitude) = ((got_value - want_value).abs(), want_value.abs());
893	            // A NaN never satisfies the comparison below, so it would be skipped
894	            // rather than reported and an all-NaN output would pass. Non-finite
895	            // values are rejected here instead of being ranked.
896	            assert!(
897	                got_value.is_finite() && want_value.is_finite(),
898	                "{what}: element {index} is not finite (got {got_value}, reference {want_value})"
899	            );
900	            // Rank by the margin against the actual bound, not by the raw
901	            // deviation: the bound is affine in `magnitude`, so the two orderings
902	            // differ, and ranking by deviation can let a large-magnitude element
903	            // past its own bound while a small-magnitude element, ranked higher,
904	            // passes. Every element is checked for that reason.
905	            let excess = abs_diff - tolerance(magnitude);
906	            if excess > worst_excess {
907	                worst_excess = excess;
908	                worst = (index, abs_diff, magnitude);
909	            }
910	        }
911	        let (index, abs_diff, magnitude) = worst;
912	        assert!(
913	            worst_excess <= 0.0,
914	            "{what}: element {index} differs by {abs_diff} (reference {magnitude}), over the \
915	             tolerance by {worst_excess}"
916	        );
917	    }
918	
919	    /// The gated norm has two activations, because Qwen3.8-Flash-Next's
920	    /// `output_gate_type` selects sigmoid where Qwen3.5 uses silu. Run at the
921	    /// Flash-Next GDN geometry (48 value heads at head_dim 128), each activation
922	    /// against its own CPU reference. The two distinct references are what pin the
923	    /// template parameter: were both entry points instantiated with one activation,
924	    /// the mismatched comparison would fail on nearly every element (silu is
925	    /// `g * sigmoid(g)`, so the two differ wherever `g` is not zero).
926	    #[test]
927	    #[ignore = "requires a GPU"]
928	    fn the_gated_norm_activations_match_their_references() {
929	        let ctx = DeviceContext::new_with_device(0).expect("device");
930	        let (num_heads, head_dim, seq_len, eps) = (48usize, 128usize, 4usize, 1e-6f32);
931	        let d = num_heads * head_dim;
932	        let x = seeded(&ctx, d, seq_len, 11);
933	        let gate = seeded(&ctx, d, seq_len, 12);
934	        let weight_host: Vec<f32> = (0..head_dim)
935	            .map(|i| ((i % 7) as f32 - 3.0) * 0.25 + 1.0)
936	            .collect();
937	        let weight = ctx.stream.clone_htod(&weight_host).expect("weight up");
938	
939	        let mut silu_out = HiddenStates::zeros(&ctx, d, seq_len).expect("silu buf");
940	        rms_norm_gated_batch_into(
941	            &ctx,
942	            &x,
943	            &weight,
944	            &gate,
945	            &mut silu_out,
946	            num_heads,
947	            head_dim,
948	            eps,
949	            GatedNormActivation::Silu,
950	        );
951	        let mut sigmoid_out = HiddenStates::zeros(&ctx, d, seq_len).expect("sigmoid buf");
952	        rms_norm_gated_batch_into(
953	            &ctx,
954	            &x,
955	            &weight,
956	            &gate,
957	            &mut sigmoid_out,
958	            num_heads,
959	            head_dim,
960	            eps,
961	            GatedNormActivation::Sigmoid,
962	        );
963	
964	        let x_host = ctx.stream.clone_dtoh(&x.data).expect("x down");
965	        let gate_host = ctx.stream.clone_dtoh(&gate.data).expect("gate down");
966	        let silu_host = ctx.stream.clone_dtoh(&silu_out.data).expect("silu down");
967	        let sigmoid_host = ctx
968	            .stream
969	            .clone_dtoh(&sigmoid_out.data)
970	            .expect("sigmoid down");
971	
972	        assert_close(
973	            &silu_host,
974	            &gated_norm_reference(&x_host, &weight_host, &gate_host, head_dim, eps, false),
975	            "silu gated norm",
976	        );
977	        assert_close(
978	            &sigmoid_host,
979	            &gated_norm_reference(&x_host, &weight_host, &gate_host, head_dim, eps, true),
980	            "sigmoid gated norm",
981	        );
982	    }
983	
984	    /// `assert_close` must not treat a non-finite value as "close": a NaN never
985	    /// wins the margin comparison, so without the finiteness check an all-NaN
986	    /// output would leave `worst_excess` at negative infinity and pass.
987	    #[test]
988	    #[should_panic(expected = "not finite")]
989	    fn assert_close_rejects_non_finite_values() {
990	        assert_close(
991	            &[bf16::from_f32(f32::NAN)],
992	            &[bf16::from_f32(1.0)],
993	            "nan output",
994	        );
995	    }
996	}
