306	/// `PEGAINFER_CUBLAS_STATUS_BASE` in `csrc/shared/ffi_guard.cuh`: an entry
307	/// point that calls cuBLAS returns it plus the `cublasStatus_t` on a cuBLAS
308	/// failure, and the `cudaError_t` otherwise.
309	pub const CUBLAS_STATUS_BASE: i32 = 100_000;
310	
311	/// Name a nonzero status from such an entry point, for an error message.
312	pub fn ffi_status_detail(status: i32) -> String {
313	    if status >= CUBLAS_STATUS_BASE {
314	        format!("cublas_status={}", status - CUBLAS_STATUS_BASE)
315	    } else {
316	        format!("cuda_status={status}")
317	    }
318	}
