14	/// RMSNorm into pre-allocated output buffer
15	pub fn rms_norm_into(
16	    ctx: &DeviceContext,
17	    x: &DeviceVec,
18	    weight: &DeviceVec,
19	    eps: f32,
20	    out: &mut DeviceVec,
21	) -> Result<()> {
22	    assert_eq!(x.len, out.len);
23	    let (x_ptr, _gx) = x.data.device_ptr(&ctx.stream);
24	    let (w_ptr, _gw) = weight.data.device_ptr(&ctx.stream);
25	    let (out_ptr, _go) = out.data.device_ptr_mut(&ctx.stream);
26	    unsafe {
27	        ffi::rms_norm_cuda(
28	            x_ptr as *const ffi::Half,
29	            w_ptr as *const ffi::Half,
30	            out_ptr as *mut ffi::Half,
31	            x.len as i32,
32	            eps,
33	            crate::tensor::active_cu_stream(ctx),
34	        );
35	    }
36	    Ok(())
37	}
