169	/// Two RMSNorms of the same input in one launch: `out_a = rms(x) * weight_a *
170	/// scale_a` and `out_b = rms(x) * weight_b`, each bitwise what its standalone
171	/// operations produce. The norms share one reduction, and the input is read
172	/// twice instead of four times.
173	#[allow(clippy::too_many_arguments)]
174	pub fn rms_norm_batch_dual_into(
175	    ctx: &DeviceContext,
176	    x: &HiddenStates,
177	    weight_a: &DeviceVec,
178	    weight_b: &DeviceVec,
179	    eps: f32,
180	    scale_a: f32,
181	    out_a: &mut HiddenStates,
182	    out_b: &mut HiddenStates,
183	) -> Result<()> {
184	    const OP: &str = "rms_norm_batch_dual_into";
185	    ensure!(
186	        x.hidden_dim > 0 && x.seq_len > 0,
187	        "{OP} dimensions must be non-zero"
188	    );
189	    ensure!(weight_a.len == x.hidden_dim, "{OP} weight_a len mismatch");
190	    ensure!(weight_b.len == x.hidden_dim, "{OP} weight_b len mismatch");
191	    ensure!(
192	        weight_a.data.len() >= x.hidden_dim,
193	        "{OP} weight_a backing too small"
194	    );
195	    ensure!(
196	        weight_b.data.len() >= x.hidden_dim,
